          id: p.id,
          contentId: p.content_id,
          platformId: normalizePlatformRef(p.platform_id, platformNameById),
          legenda: p.legenda || '',
          hashtags: p.hashtags || '',
          publishDate: p.publish_date,
          publishTime: p.publish_time,
        })),
      }));
    })

